REQUIRE-AUDIO ALSO AUDIO
CREATE BUF 192000 ALLOT
S" D:/home/source/zig/forthz/.work/998-followup/listen-wrhfoy0i/input.pcm" R/O OPEN-FILE THROW CONSTANT FD
: LOAD-PCM BUF 192000 FD READ-FILE THROW 192000 <> IF -37 THROW THEN ; LOAD-PCM
FD CLOSE-FILE THROW
VARIABLE P VARIABLE OFFSET VARIABLE SENT VARIABLE REQUEST VARIABLE WRITES
: OPEN-PCM 48000 1 32768 PCM-OPEN THROW P ! ;
: CLEANUP P @ DUP IF PCM-CLOSE DUP 0= IF 0 P ! THEN ELSE DROP 0 THEN ;
: SEND ( frames -- )
  0 SENT ! BEGIN DUP SENT @ > WHILE
    DUP SENT @ - 512 MIN REQUEST !
    BUF OFFSET @ 2 * + REQUEST @ P @ PCM-WRITE THROW
    DUP SENT +! OFFSET +! 1 WRITES +!
    DUP SENT @ > IF 1 1000 P @ PCM-WAIT THROW 0= IF -528 THROW THEN THEN
  REPEAT DROP ;
: DRAIN 1 3000 P @ PCM-STOP THROW 0= IF -528 THROW THEN ." DRAINED" CR ;
: REPORT ." UNDERRUNS=" P @ PCM-UNDERRUNS THROW .
  ." WRITES=" WRITES @ . CR ;
: TONE 0 OFFSET ! 96000 SEND ;
: BODY OPEN-PCM TONE DRAIN REPORT 250 MS ;
: RUN ['] BODY CATCH >R ['] CLEANUP CATCH DUP IF ELSE DROP THEN R> ?DUP IF SWAP DROP THROW THEN THROW ;
RUN ." COMPLETE DEPTH=" DEPTH . CR BYE

